def write(path, rows, prefix, fields):
    lines = []
    for i, row in enumerate(rows, 1):
        rec = {"id": f"{prefix}-{WP}-{i}"}
        rec.update(row)
        rec["wp"] = WP
        out = {k: rec[k] for k in fields}
        lines.append(json.dumps(out, ensure_ascii=False))
    Path(path).write_text("\n".join(lines) + "\n", encoding="utf-8")
    return len(lines)

g_fields = ["id", "title", "source", "section", "description", "evidence", "type", "area", "severity",
            "needed_by_wave", "legacy_ref", "owner_role", "asm", "proposed", "wp"]
a_fields = ["id", "text", "why", "read", "gap", "applied_in", "confidence", "confirm", "impact", "wp"]

ng = write(WORK / "gaps" / f"{WP}.jsonl", gaps, "CG", g_fields)

# assumption ids are fixed before writing: gap n pairs with ASM n
for i, a in enumerate(assumptions, 1):
    a["gap"] = f"CG-{WP}-{a['gap']}" if a["gap"] else ""

na = write(WORK / "assumptions" / f"{WP}.jsonl", assumptions, "ASM", a_fields)

print("gaps", ng, "assumptions", na)
